ubstituting (\ref{455pm91}) into (\ref{253pm94}) for $i$,
\begin{gather}
 \sum_{\sigma \in S_N}\big(p\mathbf{A}_{\sigma}\xi_{\sigma(1)}^{x_1}\cdots\xi_{\sigma(i-1)}^{x_{i-1}} \xi_{\sigma(i)}^{x_{i}}\xi_{\sigma(i+1)}^{x_{i}}\xi_{\sigma(i+2)}^{x_{i+2}}\cdots\xi_{\sigma(N)}^{x_{N}}\nonumber\\
 \qquad{} + q\mathbf{A}_{\sigma}\xi_{\sigma(1)}^{x_1}\cdots\xi_{\sigma(i-1)}^{x_{i-1}} \xi_{\sigma(i)}^{x_{i}+1}\xi_{\sigma(i+1)}^{x_{i}+1}\xi_{\sigma(i+2)}^{x_{i+2}}\cdots\xi_{\sigma(N)}^{x_{N}} \label{715pm94}\\
\qquad{} - \big(\mathbf{I}_N^{\otimes{(i-1)}} \otimes \mathbf{B}\otimes \mathbf{I}_N ^{\otimes(N-i-1)}\big)\mathbf{A}_{\sigma}\xi_{\sigma(1)}^{x_1}\cdots\xi_{\sigma(i-1)}^{x_{i-1}} \xi_{\sigma(i)}^{x_{i}}\xi_{\sigma(i+1)}^{x_{i}+1}\xi_{\sigma(i+2)}^{x_{i+2}}\cdots\xi_{\sigma(N)}^{x_{N}}\big) = \mathbf{0}_{N^N}.\nonumber
\end{gather}
If $\sigma'$ is an even permutation, then $T_i\sigma'$ is an odd permutation, and vice-versa. So, if we express~(\ref{715pm94}) as a sum over the alternating group~$A_N$,
\begin{gather}
 \sum_{\sigma' \in A_N}\big(\big[\mathbf{I}_{N^N}\big(p+q\xi_{\sigma'(i)}\xi_{\sigma'(i+1)}\big)
 - \big(\mathbf{I}_N^{\otimes{(i-1)}} \otimes \mathbf{B}\otimes \mathbf{I}_N ^{\otimes(N-i-1)}\big)\xi_{\sigma'(i+1)}\big]\mathbf{A}_{\sigma'}\nonumber \\
\qquad {} + \big[\mathbf{I}_{N^N}\big(p+q\xi_{\sigma'(i+1)}\xi_{\sigma'(i)}\big) - \big(\mathbf{I}_N^{\otimes{(i-1)}} \otimes \mathbf{B}\otimes \mathbf{I}_N ^{\otimes(N-i-1)}\big)\xi_{\sigma'(i)}\big]\mathbf{A}_{T_i\sigma'}\big)\nonumber\\
\qquad {} \times \xi_{\sigma'(1)}^{x_1}\cdots\xi_{\sigma'(i-1)}^{x_{i-1}}\xi_{\sigma'(i)}^{x_{i}} \xi_{\sigma'(i+1)}^{x_{i}}\xi_{\sigma'(i+2)}^{x_{i+2}}\cdots \xi_{\sigma'(N)}^{x_{N}} = \mathbf{0}_{N^N}.\label{1117pm95}
\end{gather}
A sufficient condition for (\ref{1117pm95}) is that for each $\sigma \in S_N$,
\begin{gather}
\mathbf{A}_{T_i\sigma} = - \big[\mathbf{I}_{N^N}\big(p+q\xi_{\sigma(i+1)}\xi_{\sigma(i)}\big) - \big(\mathbf{I}_N^{\otimes{(i-1)}} \otimes \mathbf{B}\otimes \mathbf{I}_N ^{\otimes(N-i-1)}\big)\xi_{\sigma(i)}\big]^{-1}\nonumber\\
\hphantom{\mathbf{A}_{T_i\sigma} =}{} \times \big[\mathbf{I}_{N^N}\big(p+q\xi_{\sigma(i)}\xi_{\sigma(i+1)}\big) - \big(\mathbf{I}_N^{\otimes{(i-1)}} \otimes \mathbf{B}\otimes \mathbf{I}_N ^{\otimes(N-i-1)}\big)\xi_{\sigma(i+1)}\big] \mathbf{A}_{\sigma}\nonumber \\
\hphantom{\mathbf{A}_{T_i\sigma}}{} = -\big(\mathbf{I}_{N^{(i-1)}}\otimes \big[\mathbf{I}_{N^2}\big(p+q\xi_{\sigma(i+1)}\xi_{\sigma(i)}\big) - \mathbf{B} \xi_{\sigma(i)} \big]^{-1} \otimes \mathbf{I}_{N^{(N-i-1)}}\big)\nonumber \\
\hphantom{\mathbf{A}_{T_i\sigma} =}{} \times \big(\mathbf{I}_{N^{(i-1)}}\otimes \big[\mathbf{I}_{N^2}\big(p+q\xi_{\sigma(i+1)}\xi_{\sigma(i)}\big) - \mathbf{B} \xi_{\sigma(i+1)} \big] \otimes \mathbf{I}_{N^{(N-i-1)}}\big)\mathbf{A}_{\sigma} \nonumber\\
\hphantom{\mathbf{A}_{T_i\sigma} }{}= \big(\mathbf{I}_{N^{(i-1)}}\otimes \mathbf{R}_{\sigma(i+1)\sigma(i)} \otimes \mathbf{I}_{N^{(N-i-1)}}\big)\mathbf{A}_{\sigma}. \label{1151pm95}
\end{gather}
Now, it remains to show that if $\mathbf{A}_{\sigma}$ is given by (\ref{148am511}), then (\ref{1151pm95}) is satisfied. This is immediately obtained because
\begin{gather*}
\mathbf{A}_{T_i\sigma} = \mathbf{T}_i\mathbf{T}_{a_n} \cdots \mathbf{T}_{a_1} = \mathbf{T}_i\big(\sigma(i+1),\sigma(i)\big)\mathbf{A}_{\sigma} \\
\hphantom{\mathbf{A}_{T_i\sigma}}{} = \big(\mathbf{I}_{N^{(i-1)}}\otimes \mathbf{R}_{\sigma(i+1)\sigma(i)} \otimes \mathbf{I}_{N^{(N-i-1)}}\big)\mathbf{A}_{\sigma}
\end{gather*}
by (\ref{1243-am-519}).

The consistency relations
\begin{gather}
 \mathbf{T}_i(\beta,\alpha)\mathbf{T}_j(\delta,\gamma) = \mathbf{T}_j(\delta,\gamma)\mathbf{T}_i(\beta,\alpha) \qquad \textrm{if}~|i - j| \geq 2,\nonumber \\
\mathbf{T}_i(\gamma,\beta)\mathbf{T}_j(\gamma,\alpha)\mathbf{T}_i(\beta,\alpha) = \mathbf{T}_j(\beta,\alpha) \mathbf{T}_i(\gamma,\alpha)\mathbf{T}_j(\gamma,\beta) \qquad \textrm{if}~|i-j| = 1, \nonumber\\
\mathbf{T}_i(\beta,\alpha) \mathbf{T}_i(\alpha,\beta) = \mathbf{I}_{N^N}\label{617pm93}
\end{gather}
can be directly verified by the matrix multiplication. In particular, (\ref{617pm93}) with $p=1$ was verified in~\cite{Chatterjee-Schutz-2010}.

For given $Y = (y_1,\dots, y_N)$ with $y_1<\cdots<y_N$ and $\pi$, define
\begin{gather*}
G(x_1,\dots, x_N;t) = \left[
 \begin{matrix}
 F_{n(1,1)}(x_1 - y_1;t)\!\! & F_{n(1,2)}(x_1 - y_2;t)\!\! & \!\!\cdots\!\! & F_{n(1,N)}(x_1 - y_N;t) \\
 F_{n(2,1)}(x_2 - y_1;t)\!\! & F_{n(2,2)}(x_2 - y_2;t)\!\! & \!\!\cdots\!\! & F_{n(2,N)}(x_2 - y_N;t) \\
 \vdots & \vdots & \!\!\ddots\!\! & \vdots \\
 F_{n(N,1)}(x_N - y_1;t)\!\! & F_{n(N,2)}(x_N - y_2;t)\!\! & \!\!\cdots\!\! & F_{(N,N)}(x_N - y_N;t)
 \end{matrix}
 \right].
\end{gather*}
Then,
\begin{equation*}
P_{(Y,\pi)}(x_1,\dots,x_N,\pi;t) = \det G(x_1,\dots, x_N;t).
\end{equation*}

i) To show that $\det G(x_1,\dots, x_N;t)$ satisfies (\ref{503am814}).
Since
\begin{equation*}
\frac{{\rm d}}{{\rm d}t}F_{n(i,j)}(x_i - y_j;t) = -F_{n(i,j)}(x_i - y_j;t) + F_{n(i,j)}(x_i -1 - y_j;t),
\end{equation*}
we have
\begin{gather*}
\frac{{\rm d}}{{\rm d}t} \det G(x_1,\dots, x_N;t) \\
\qquad{} = \left|
 \begin{matrix}
\dfrac{{\rm d}}{{\rm d}t} F_{n(1,1)}(x_1 - y_1;t) & \dfrac{{\rm d}}{{\rm d}t}F_{n(1,2)}(x_1 - y_2;t) & \cdots & \dfrac{{\rm d}}{{\rm d}t} F_{n(1,N)}(x_1 - y_N;t) \vspace{1mm}\\
 F_{n(2,1)}(x_2 - y_1;t) & F_{n(2,2)}(x_2 - y_2;t) & \cdots & F_{n(2,N)}(x_2 - y_N;t) \\
 \vdots & \vdots & \ddots & \vdots \\
 F_{n(N,1)}(x_N - y_1;t) & F_{n(N,2)}(x_N - y_2;t) & \cdots & F_{(N,N)}(x_N - y_N;t)
 \end{matrix}
 \right| +\cdots \\
\qquad\quad{} + \left|
 \begin{matrix}
 F_{n(1,1)}(x_1 - y_1;t) &F_{n(1,2)}(x_1 - y_2;t) & \cdots & F_{n(1,N)}(x_1 - y_N;t) \\
F_{n(2,1)}(x_2 - y_1;t) & F_{n(2,2)}(x_2 - y_2;t) & \cdots & F_{n(2,N)}(x_2 - y_N;t) \\
 \vdots & \vdots & \ddots & \vdots \\
\dfrac{{\rm d}}{{\rm d}t} F_{n(N,1)}(x_N - y_1;t) & \dfrac{{\rm d}}{{\rm d}t} F_{n(N,2)}(x_N - y_2;t) & \cdots & \dfrac{{\rm d}}{{\rm d}t} F_{(N,N)}(x_N - y_N;t)
 \end{matrix}
 \right| \\
 \qquad{} = -N \det G(x_1,\dots, x_N;t) +\sum_{i=1}^N\det G(x_1,\dots,x_{i-1},x_i-1,x_{i+1},\dots, x_N;t).
\end{gather*}

(ii) To show that $\det G(x_1,\dots, x_N;t)$ satisfies (\ref{548am814}): Suppose that $\pi_i>\pi_{i+1}$. First, we will show that $n(i,j) = n(i+1,j)$. If $j>i+1$, then
\begin{equation*}
n(i,j) = (-1) \times (j-i -\#_{ij}) = (-1) \times \big[j-(i+1) -(\underbrace{\#_{ij}-1}_{\#_{(i+1)j}})\big] = n(i+1,j).
\end{equation*}
If $j<i-1$, then
\begin{equation*}
n(i,j) = 1 \times (i-j -\#_{ij}) = 1 \times \big[i+1-j -(\underbrace{\#_{ij}+1}_{\#_{(i+1)j}})\big] = n(i+1,j).
\end{equation*}
If $i=j$ or $j=i\pm 1$, then
\begin{equation*}
n(i,j) = 0 = n(i+1,j).
\end{equation*}
Hence, the $i$th row and the $(i+1)$th row of $G(x_1,\dots, x_i,x_i,x_{i+2},\dots,x_N;t)$ are the same and
\begin{equation*}
\det G(x_1,\dots, x_i,x_i,x_{i+2},\dots,x_N;t) = 0.
\end{equation*}
 Next, suppose that $\pi_i \leq \pi_{i+1}$, so $\#_{ij} = \#_{(i+1)j}$. We will show that $n(i,j) = n(i+1,j)-1$.
If $j>i+1$, then
\begin{equation*}
n(i+1,j) = (-1) \times (j-i-1 -\#_{(i+1)j}) = (-1) \times (j-i -\#_{ij}) + 1 = n(i,j)+1.
\end{equation*}
If $j<i-1$, then
\begin{equation*}
n(i+1,j) = 1 \times (i+1-j -\#_{(i+1)j}) = 1 \times (i-j -\#_{ij}) +1 = n(i,j) +1.
\end{equation*}
If $i=j$, then $n(i+1,j) = 1 = n(i,i) +1$. If $j = i +1$, then $n(i+1,j) = 0 = n(i,j) +1.$ If $j = i-1$, then
\begin{gather}
n(i+1,j) = (+1)\times (2 - \#_{(i-1)(i+1)})= (+1)\times (2 - \#_{(i-1)i}) \nonumber\\
 \hphantom{n(i+1,j)}{} =(+1)\times (1 - \#_{(i-1)i}) + 1 = n(i,i-1) + 1 = n(i,j)+1.\label{740pm815}
\end{gather}
Also, using the identity
\begin{equation*}
F_n(x+1;t) = F_n(x;t) - F_{n-1}(x;t),
\end{equation*}
we obtain
\begin{gather}
 \left|
 \begin{matrix}
 \vdots & \vdots & \vdots \\
 F_{n(i,1)}(x_i - y_1;t) & \cdots & F_{n(i,N)}(x_i - y_N;t) \\
 F_{n(i+1,1)}(x_{i}+1 - y_1;t) & \cdots & F_{n(i+1,N)}(x_{i}+1 - y_N;t) \\
 \vdots & \vdots & \vdots
 \end{matrix}
 \right| \nonumber\\
\qquad{} = \left|
 \begin{matrix}
 \vdots & \vdots & \vdots \\
 F_{n(i,1)}(x_i - y_1;t) & \cdots & F_{n(i,N)}(x_i - y_N;t) \\
 F_{n(i+1,1)}(x_{i} - y_1;t) & \cdots & F_{n(i+1,N)}(x_{i} - y_N;t) \\
 \vdots & \vdots & \vdots \\
 \end{matrix}
 \right| \nonumber\\
\qquad\quad{} - \left|
 \begin{matrix}
 \vdots & \vdots & \vdots \\
 F_{n(i,1)}(x_i - y_1;t) & \cdots & F_{n(i,N)}(x_i - y_N;t) \\
 F_{n(i+1,1)-1}(x_{i} - y_1;t) & \cdots & F_{n(i+1,N)-1}(x_{i} - y_N;t) \\
 \vdots & \vdots & \vdots
 \end{matrix}
 \right|, \label{745pm815}
\end{gather}
where the second term on the right-hand side of (\ref{745pm815}) is zero by (\ref{740pm815}). Hence,
\begin{equation*}
\det G(x_1,\dots, x_i,x_i+1,x_{i+2},\dots,x_N;t) = \det G(x_1,\dots, x_i,x_i,x_{i+2},\dots,x_N;t).
\end{equation*}

(iii) To show that $\det G(x_1,\dots, x_N)$ satisfies (\ref{209pm98}): Since $F_{n(i,i)}(x_i - y_i;0) = \delta_{x_iy_i}$ and $F_{n(i,j)}(x_i - y_j;0) =0$ for $i>j$ because $x_i - y_j \geq 1$ when $x_1<\cdots <x_N$ for given $y_1<\cdots <y_N$,
 \begin{equation*}
 \det G(x_1,\dots,x_N;0) = \prod_{i=1}^N\delta_{x_iy_i}
 \end{equation*}
 when $x_1<\cdots <x_N$ for given $y_1<\cdots <y_N$.
